-- Trip Shed VVH Step 5 exact GC source checklist restoration
-- Adds source-restored GC template and disables entry on abbreviated template 1; historical records keep template_id=1.
START TRANSACTION;
UPDATE div_trip_inspection_templates SET entry_enabled=0 WHERE id=1 AND inspection_type='GC';
SET @gc_source_template_id = LAST_INSERT_ID();
COMMIT;
